INSERT INTO "digital_skills" ("skill_id", "name", "description") VALUES ("1", "HTML", "HTML tells the web browser how it should define and display content. For content marketing, it is essential to understand how to find and edit meta descriptions, title tags and keywords.");
INSERT INTO "digital_skills" ("skill_id", "name", "description") VALUES ("2", "Scripting", "This could be Bash, Python or even Perl. Bash is a command line interpreter, Python is a dynamic language, while Perl is general purpose. All of them support scripts — programs written to automate tasks that could also be executed manually by a human.");
INSERT INTO "digital_skills" ("skill_id", "name", "description") VALUES ("3", "Data Analysis", "This is SQL & Excel. SQL is a programming language designed for managing data held in a relational database management system. They have data definition, manipulation and control languages. As a marketer, you would be using the manipulation language, or querying.");
INSERT INTO "digital_skills" ("skill_id", "name", "description") VALUES ("4", "Data Visualisation", "Data visualisation is the presentation of information in a graphical format, usually a chart, sometimes a pictorial representation. They enable decision makers to see analytics visually and draw conclusions at a glance. They can convey a lot of information in a relatively small amount of screen real estate.");
INSERT INTO "digital_skills" ("skill_id", "name", "description") VALUES ("5", "Understanding of programming concepts", "It’s very useful to understand the applications of different programming languages and the complexity of various tasks. You should also understand, for example, the capability of APIs and multivariate testing.");
